    def(8, 0, -600, 0, 8, 0, 78, 0, 1, .scroll, 1.0), // low-sky sprites (world)
    def(9, 0, 450, 0, 4, 0, 142, 0, -1, .scroll, 1.0), // floor
    def(10, 0, 600, 0, 8, 0, 174, 0, -1, .scroll, 1.0), // ground top
    def(11, 0, 800, 0, 8, 0, 190, 0, -1, .scroll, 1.0), // ground bottom
    def(12, 0, 206, 0, 0, 0, 206, 0, 0, .fade, 0.001), // bottom
